        "originalUrl": "https://cdn.discordapp.com/attachments/1269536886586609695/1346014878871195658/dont_give_up.mp4?ex=6afe9f0a&is=6afd4d8a&hm=8e4b0e0707956f3fdcbb1a8139bd2e55befdabb82df1a55b5fcd58d231b89156&",
